package com.turboio.androidtests;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.lang.reflect.*;import java.time.*;import java.util.*;import java.util.concurrent.atomic.*;import java.util.function.Consumer;
/** Installed production scroll view, synthetic dates only; no material changes or requests. */
public final class WeekStripProbe extends Instrumentation {
 private Activity activity;private View strip;private Dialog dialog;private int checks;private final AtomicInteger callbacks=new AtomicInteger();private final List<Integer> samples=new ArrayList<>();private LocalDate chosen;
 public void onCreate(Bundle args){super.onCreate(args);start();}
 private void check(boolean value){checks++;if(!value)throw new AssertionError("WEEK_STRIP_CHECK_"+checks);}
 private void create()throws Exception{runOnMainSync(()->{try{if(dialog!=null)dialog.dismiss();Class<?> c=activity.getClassLoader().loadClass("com.turboio.addon.MaterialWeekStrip");Constructor<?> ctor=c.getDeclaredConstructor(Activity.class,LocalDate.class,Set.class,Consumer.class,Runnable.class);ctor.setAccessible(true);strip=(View)ctor.newInstance(activity,LocalDate.of(2026,10,26),Collections.emptySet(),(Consumer<LocalDate>)day->{chosen=day;callbacks.incrementAndGet();},(Runnable)()->{});dialog=new Dialog(activity);dialog.setContentView(strip,new ViewGroup.LayoutParams(-1,-1));dialog.show();dialog.getWindow().setLayout(1000,240);}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(300);}
 private void send(long down,int action,float x){runOnMainSync(()->{MotionEvent e=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,x,90,0);strip.dispatchTouchEvent(e);e.recycle();samples.add(strip.getScrollX());});}
 private int x(){int[] result={0};runOnMainSync(()->result[0]=strip.getScrollX());return result[0];}
 public void onStart(){Bundle out=new Bundle();try{Context app=getTargetContext();activity=startActivitySync(new Intent().setClassName(app,"com.rayneo.venus.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));create();int baseline=x();out.putInt("viewport_width",strip.getWidth());out.putInt("initial_scroll",baseline);check(baseline>0);long down=SystemClock.uptimeMillis();send(down,0,850);for(int i=1;i<=12;i++){Thread.sleep(24);send(down,2,850-i*50);}check(callbacks.get()==0);check(x()>baseline+450);send(down,1,250);Set<Integer> releaseFrames=new HashSet<>();for(int i=0;i<120&&callbacks.get()==0;i++){Thread.sleep(16);releaseFrames.add(x());}check(callbacks.get()==1);check(chosen!=null&&chosen.isAfter(LocalDate.of(2026,10,26)));out.putInt("distinct_release_positions",releaseFrames.size());out.putString("release_positions",releaseFrames.toString());check(releaseFrames.size()>3);out.putInt("distinct_drag_positions",new HashSet<>(samples).size());out.putBoolean("no_day_callback_during_drag",true);
  create();callbacks.set(0);baseline=x();down=SystemClock.uptimeMillis();send(down,0,850);for(int i=1;i<=8;i++){Thread.sleep(24);send(down,2,850-i*45);}send(down,3,490);Thread.sleep(800);check(callbacks.get()==0);check(x()==baseline);out.putBoolean("cancel_returns_without_selecting",true);
  create();callbacks.set(0);baseline=x();down=SystemClock.uptimeMillis();send(down,0,850);for(int i=1;i<=8;i++){Thread.sleep(24);send(down,2,850-i*45);}send(down,1,490);Thread.sleep(32);long reverse=SystemClock.uptimeMillis();runOnMainSync(()->{int before=strip.getScrollX();MotionEvent e=MotionEvent.obtain(reverse,reverse,0,250,90,0);strip.dispatchTouchEvent(e);e.recycle();check(strip.getScrollX()==before);});for(int i=1;i<=6;i++){Thread.sleep(24);send(reverse,2,250+i*45);}send(reverse,3,520);Thread.sleep(800);check(callbacks.get()==0&&x()==baseline);out.putBoolean("reverse_drag_interrupts_fling_without_jump",true);
  create();callbacks.set(0);down=SystemClock.uptimeMillis();send(down,0,850);for(int i=1;i<=8;i++){Thread.sleep(24);send(down,2,850-i*45);}send(down,1,490);Thread.sleep(32);runOnMainSync(()->dialog.dismiss());Thread.sleep(500);check(callbacks.get()==0);out.putBoolean("detached_animation_cannot_select",true);out.putBoolean("passed",true);out.putInt("checks",checks);
 }catch(Throwable e){while(e.getCause()!=null)e=e.getCause();out.putBoolean("passed",false);String msg=e.getMessage();out.putString("error",msg!=null&&msg.matches("[A-Z_0-9]{3,80}")?msg:e.getClass().getSimpleName());}finally{runOnMainSync(()->{if(dialog!=null)dialog.dismiss();});finish(Activity.RESULT_OK,out);}}
}
